def nextWithoutFour(digits):
    res = list(digits)
    i = len(res) - 1
    while i >= 0 and res[i] == 9:
        res[i] = 0
        i -= 1
    if i < 0:
        res.insert(0, 1)
    else:
        res[i] += 1
    for j in range(len(res)):
        if res[j] == 4:
            res[j] = 5
            for t in range(j + 1, len(res)):
                res[t] = 0
            break
    return res
